const data = $input.first().json;
const groups = data.results || [{ query: data.query || 'rog ally', total_found: data.total_found || 0, top_listings: data.top_listings || [] }];
return groups.map(g => ({ json: g }));

const MARKET = {
  'rog ally':  '- ROG Ally Z1 Extreme (2023): 7000-11000 Kč used, 11000-14000 Kč like-new\n- ROG Ally X (2024): 13000-18000 Kč used, 18000-23000 Kč like-new',
  'legion go': '- Lenovo Legion Go (2023, Z1 Extreme): 10000-15000 Kč used, 15000-19000 Kč like-new',
  'msi claw':  '- MSI Claw A1M (Intel Core Ultra, 2024): 8000-13000 Kč used, 13000-17000 Kč like-new',
};

function renderListings(listings) {
  return listings.map(l => {
    const price = l.buy_now_czk
      ? `${l.price_czk} Kč bid / ${l.buy_now_czk} Kč buy-now`
      : `${l.price_czk} Kč${l.is_auction ? ' (auction, current bid)' : ' (fixed price)'}`;
    const newTag = l.is_new ? ' [NEW]' : '';
    const sellerParts = [`${l.seller_reviews ?? '?'} reviews`, `${l.seller_positive_pct ?? '?'}% positive`];
    if (l.seller_rating) sellerParts.push(`${l.seller_rating}★`);
    const stats = [];
    if (l.bidders_count != null) stats.push(`${l.bidders_count} bidders`);
    if (l.watchers_count) stats.push(`${l.watchers_count} watchers`);
    if (l.cheapest_shipping) stats.push(`shipping: ${l.cheapest_shipping}`);
    const attrLines = l.attributes
      ? Object.entries(l.attributes).filter(([k]) => k !== 'Stav zboží').map(([k,v]) => `  ${k}: ${v}`).join('\n')
      : '';
    return [
      `--- LISTING${newTag} ---`,
      `Title: ${l.title}`,
      `Price: ${price}`,
      `Condition: ${l.condition}`,
      `Time left: ${l.time_left}`,
      `Seller: ${l.seller_name || l.seller} — ${sellerParts.join(', ')}`,
      stats.length ? stats.join(' | ') : '',
      attrLines ? `Attributes:\n${attrLines}` : '',
      l.description ? `Description: ${l.description.slice(0, 200)}` : '',
      `URL: ${l.url}`,
    ].filter(Boolean).join('\n');
  }).join('\n\n');
}

const items = $input.all();
return items.map(item => {
  const g = item.json;
  const key = (g.query || '').toLowerCase();
  const market = Object.entries(MARKET).find(([k]) => key.includes(k.split(' ')[0]))?.[1] || '';
  const listings = g.top_listings || [];
  const deviceLabel = g.query.toUpperCase();

  const prompt = `You are a deal-analysis assistant for aukro.cz. A Czech buyer is looking for a ${deviceLabel}.

Market prices (CZK, 2026):
${market}

Rules:
- Condition: Nové > Zánovní > Rozbaleno > Použité > Poškozeno
- Auction price = current bid, NOT the final price. 0 bidders = unknown final price.
- Buy-now = fixed immediate price. Many bidders on auction = likely to exceed market — flag it.
- 0 reviews is completely normal — most sellers are private individuals selling a single device. Never flag 0 reviews as a risk. Only flag if feedback % is under 90% (when reviews exist).
- Extras (SD card, dock, case, warranty) add value — mention if present.

Today's top ${listings.length} listings (${g.total_found} total on aukro.cz):

${listings.length ? renderListings(listings) : '(no listings found today)'}

Write a SHORT friendly briefing for this device ONLY. Max 10 lines.

Format exactly:
### ${deviceLabel}
**Worth checking:**
→ [short title] — {price} — ends {time_left} — {condition} — {url}
  💬 one sentence: deal assessment

**New since yesterday:** {titles or nothing new}
**Skip:** {what and why, 1 line}`;

  return { json: { prompt, device: g.query } };
});

const summaries = items.map(i => i.json.text || '').join('

---

');
return [{ json: { combined_summary: summaries } }];

const agentOutput = $input.first().json.combined_summary || '';
const now = new Date().toLocaleString('cs-CZ', { timeZone: 'Europe/Prague' });
const subject = `🎮 Handheld Gaming Deals on Aukro — ${now}`;
const html = '<html><body style="font-family:monospace;font-size:14px;background:#1a1a1a;color:#e0e0e0;padding:20px">
' +
  '<h2 style="color:#f5a623">🎮 ' + subject + '</h2>
' +
  '<pre style="white-space:pre-wrap;line-height:1.6">' +
  agentOutput.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') +
  '</pre></body></html>';
return [{ json: { subject, body: agentOutput, html, timestamp: now } }];

const { subject, body, html } = $input.first().json;
const date = new Date().toISOString().slice(0, 10);
const md = `# ${subject}

${body}
`;
return [{ json: { date, md, html } }];
